-- Praktische informatie, huisregels en annuleren op /lodge-de-eik.
--
-- Zelfde drie blokken als /lodge-de-heide gekregen heeft. Het zijn
-- terreinbrede afspraken, geen eigenschappen van een afzonderlijke lodge:
-- de incheckvensters, de huisregels en de annuleringsstaffel gelden voor
-- allebei. De waarden zijn daarom letterlijk gelijk, en net als bij De Heide
-- gecontroleerd tegen /faq, de JSON-LD, lib/stay-dates.ts, het fee-sjabloon
-- 'Huisdier' en artikel 4.1 en 4.3 van /terms.
--
-- NIET meegenomen, omdat de gegevens ontbreken: de kamerindeling en de
-- specificatieregel (oppervlak, slaapkamers, badkamer). Voor De Heide zijn
-- die door de eigenaar aangeleverd; voor De Eik staat alleen "ruimte voor
-- maximaal vier personen, verdeeld over twee slaapplekken" in de tekst, en
-- dat is te vaag om er een tabel van te maken. Zodra de indeling bekend is,
-- komt er een migratie bij die hem toevoegt.
--
-- De JSON is gegenereerd uit src/lib/landing-seed.ts. Wie de secties
-- aanpast, genereert deze migratie opnieuw.
--
-- Idempotent.

update landing_pages
   set sections = '[{"eyebrow": "De inventaris", "heading": "Wat er in de lodge zit", "body": ["De Eik is de ruimste van de twee. Dat merkt u vooral aan de hoogte: het is een omgebouwd gebouw met hoge plafonds, en dat maakt een verblijf met vier mensen aanzienlijk minder krap dan de vierkante meters doen vermoeden."], "bullets": ["Ruimte voor maximaal vier personen, verdeeld over twee slaapplekken.", "Volledig uitgeruste binnenkeuken: oven, kookplaat, koelkast, vaatwasser, servies en pannen.", "Buitenkeuken met BBQ onder de eiken, met de eettafel op hetzelfde terras.", "Privé-hottub op het terras, het hele jaar door op 38 °C.", "Gratis snel WiFi, gratis parkeren op eigen terrein en een gratis EV-laadpaal.", "Digitale sloten: inchecken kan tot middernacht zonder dat iemand op u wacht."]}, {"eyebrow": "Het onderscheid", "heading": "De buitenkeuken en de BBQ", "body": ["Buiten koken is iets anders dan een BBQ op het gras zetten. Hier staat een echte buitenkeuken: werkblad, BBQ en de ruimte om alles klaar te maken zonder tien keer naar binnen te lopen. Dat verandert hoe een avond verloopt — u staat niet om beurten binnen te koken terwijl de rest buiten zit, u bent er gewoon allemaal.", "De eiken erboven doen de rest. Ze houden de middagzon eruit, waardoor het terras ook in juli bruikbaar blijft, en ze maken het geluid zachter dan u van een terras gewend bent. Als het eten op is, staat de hottub op twee meter.", "Wat hier niet staat is een sauna. Die zit in de andere lodge, en dat is een eerlijk verschil in plaats van een omissie: [vergelijk met De Heide](/lodge-de-heide) als wellness voor u zwaarder weegt dan buiten koken."]}, {"eyebrow": "Voor wie", "heading": "Voor wie deze lodge is", "body": ["De Eik is de lodge voor gezelschappen die samen willen eten. Twee stellen die om beurten koken, een gezin met kinderen die de hele dag buiten zijn, of vier vrienden die vooral een lange tafel en een BBQ nodig hebben.", "Ook met z''n tweeën werkt hij, en dan vooral in het voor- en naseizoen: de ruimte is dan luxe in plaats van overmaat. Zoekt u een weekend dat om wellness draait, dan is De Heide met haar sauna de betere keuze."]}, {"eyebrow": "De ligging", "heading": "Onder de eiken in Zeijen", "body": ["Zeijen is een van de brinkdorpen van Drenthe: een kerk, een brink, en daaromheen vrijwel meteen het veld. De lodge staat aan de rand daarvan, met de eiken eromheen en de Zeijerstrubben op loopafstand. Het centrum van Assen ligt op twintig minuten, wat ver genoeg is om er ''s avonds niets van te merken.", "Vanaf de deur beginnen de wandelroutes; er lopen meer dan 1.000 kilometer fietspaden door de omgeving en de e-bike laadt u op de laadpaal op het terrein. Wie hier komt voor de streek zelf, vindt de routes op onze pagina''s over [wandelroutes in Drenthe](/wandelroutes-drenthe) en [fietsen in Drenthe](/fietsen-in-drenthe)."]}, {"eyebrow": "Praktisch", "heading": "Prijzen en beschikbaarheid", "body": ["De prijs begint bij €165 per nacht voor de hele lodge, niet per persoon. In de schoolvakanties, rond feestdagen en in het hoogseizoen ligt hij hoger. Bovenop de nachtprijs komen schoonmaakkosten en toeristenbelasting van de gemeente Tynaarlo; boekingskosten rekenen wij niet, omdat u rechtstreeks bij de eigenaar boekt.", "Losse nachten verhuren wij niet. Er zijn twee wisseldagen — maandag en vrijdag — en daarmee drie vormen:"], "table": {"head": ["Vorm", "Aankomst", "Vertrek", "Nachten"], "rows": [["Weekend", "Vrijdag", "Zondag", "2"], ["Midweek", "Maandag", "Vrijdag", "4"], ["Week", "Maandag", "Zondag", "6"]], "note": "U geeft uw datums door en krijgt binnen 24 uur een persoonlijk voorstel met de volledige prijsopbouw: nachtprijs, schoonmaak en toeristenbelasting als aparte regels."}}, {"eyebrow": "Praktische informatie", "heading": "Aankomst, vertrek en verhuurperiodes", "body": ["De dingen waar een boeking op vastloopt als u ze pas achteraf leest."], "table": {"head": ["Onderwerp", "Details"], "rows": [["Geschikt voor", "1 – 4 personen"], ["Verhuurperiodes", "Midweek (ma – vr), weekend (vr – zo) of week (ma – zo)"], ["Inchecken", "Van 15:00 tot 21:00"], ["Uitchecken", "Uiterlijk 11:00"]], "note": "Later aankomen dan 21:00 kan zonder extra kosten: de lodge heeft digitale sloten die tot middernacht werken, en er is geen receptie waar u zich hoeft te melden."}}, {"eyebrow": "Huisregels", "heading": "Wat we van u vragen", "body": ["Kort, en er staat niets tussen dat u niet had verwacht. Eén ervan is hier extra van belang, want de BBQ staat buiten: roken doet u op de daarvoor bestemde plek."], "bullets": ["Binnen wordt niet gerookt. Buiten mag het, op de daarvoor bestemde plek.", "Huisdieren zijn toegestaan tegen een eenmalige toeslag van €25.", "Geen feesten of evenementen.", "Tussen 22:00 en 08:00 uur geldt de nachtrust.", "Alleen de directe omgeving van de accommodatie is vuurwerkvrij."]}, {"eyebrow": "Annuleren", "heading": "Als uw plannen veranderen", "body": ["De volledige voorwaarden staan in de [algemene voorwaarden](/terms); dit is de samenvatting die er voor uw boeking toe doet."], "bullets": ["Tot 60 dagen voor aankomst krijgt u alles terug, op €25 administratiekosten na.", "Tussen 60 en 30 dagen voor aankomst 70%, tussen 30 en 14 dagen 50% en tussen 14 en 7 dagen 25%.", "Binnen 7 dagen voor aankomst is er geen restitutie.", "Omboeken kan tot 30 dagen voor aankomst, na goedkeuring en afhankelijk van beschikbaarheid. Daarvoor geldt een wijzigingsvergoeding van €25."]}, {"eyebrow": "De keuze", "heading": "De Eik of De Heide?", "body": ["Kort: De Eik heeft de buitenkeuken en de ruimte, De Heide heeft de sauna en het panoramisch uitzicht. Verder zijn ze gelijkwaardig — beide voor vier personen, beide met een eigen hottub, beide volledig privé en op hetzelfde terrein.", "Weet u het nog niet, kies dan op wat u ''s avonds wilt doen. Buiten eten met de BBQ aan: De Eik. De sauna in en daarna het water: De Heide."]}]'::jsonb,
       updated_at = now()
 where slug = 'lodge-de-eik';

-- Controle: hoort 9 secties te geven.
--
--   select jsonb_array_length(sections) as secties,
--          jsonb_path_query_array(sections, '$[*].heading') as koppen
--     from landing_pages
--    where slug = 'lodge-de-eik';
